<?php
if(getenv('INSTAPASS_ISOLATED_TEST')!=='yes')throw new RuntimeException('Isolated clone required');
if(!class_exists('Instapass_Control_Bulk'))require '/var/www/html/wp-content/plugins/instapass-control-center/instapass-control-center.php';
add_filter('pre_wp_mail','__return_true',999);add_filter('pre_http_request',fn()=>new WP_Error('isolated','No outbound HTTP'),999);
wp_set_current_user(1);
$server=rest_get_server();if(!isset($server->get_routes()['/instapass-control/v1/catalog']))Instapass_Control_Bulk::routes();
$GLOBALS['pass']=[];$GLOBALS['fail']=[];$GLOBALS['fixtures']=[];
function check_bulk($name,$fn){global $pass,$fail;try{$fn();$pass[]=$name;fwrite(STDERR,'PASS '.$name."\n");}catch(Throwable $e){fwrite(STDERR,'FAIL '.$name.': '.$e->getMessage()."\n");$fail[]=['check'=>$name,'message'=>$e->getMessage()];}}
function demand($v,$message='Unexpected result'){if(!$v)throw new RuntimeException($message);}
function call_bulk($name,$body=[]){$req=new WP_REST_Request(in_array($name,['catalog','history'],true)?'GET':'POST','/instapass-control/v1/'.$name);$req->set_header('content-type','application/json');$req->set_body(wp_json_encode($body));return rest_do_request($req);}
function good_bulk($name,$body=[]){$r=call_bulk($name,$body);demand($r->get_status()<300,wp_json_encode($r->get_data()));return $r->get_data();}
function bad_bulk($name,$body=[]){$r=call_bulk($name,$body);demand($r->get_status()>=400,'Request was incorrectly accepted');$data=$r->get_data();demand(($data['code']??'')!=='rest_no_route','Test route was not registered');return $data;}
function fixture_bulk($sku,$usd,$gbp){global $fixtures;$p=new WC_Product_Simple();$p->set_name('QA BULK '.$sku);$p->set_sku($sku);$p->set_status('draft');$p->set_virtual(true);$p->set_regular_price($usd);$p->set_price($usd);if($gbp!=='')$p->update_meta_data('_instapass_gbp_regular_price',$gbp);$id=$p->save();$fixtures[]=$id;return $id;}
function price_bulk($id,$c='USD'){$p=wc_get_product($id);return $c==='GBP'?[(string)$p->get_meta('_instapass_gbp_regular_price',true,'edit'),(string)$p->get_meta('_instapass_gbp_sale_price',true,'edit')]:[(string)$p->get_regular_price('edit'),(string)$p->get_sale_price('edit')];}
function selected_bulk($id,$c='USD',$discount='25'){return good_bulk('preview',['mode'=>'selected','currency'=>$c,'discount'=>$discount,'ids'=>[$id]]);}
function apply_bulk($op){return good_bulk('apply',['token'=>$op['token']]);}
function undo_bulk($op){return good_bulk('undo',['token'=>$op['token']]);}
$originals=[];foreach(wc_get_orders(['limit'=>-1]) as $o)$originals[$o->get_id()]=[$o->get_currency(),$o->get_total(),$o->get_status()];
$products_before=[];foreach(wc_get_products(['limit'=>-1,'status'=>['publish','draft','pending','private','future']]) as $p)$products_before[$p->get_id()]=[$p->get_regular_price('edit'),$p->get_sale_price('edit'),$p->get_meta('_instapass_gbp_regular_price',true,'edit'),$p->get_meta('_instapass_gbp_sale_price',true,'edit'),$p->get_status(),$p->get_stock_status()];
$a=fixture_bulk('QA-BULK-A','19.99','22.00');$b=fixture_bulk('QA-BULK-B','1.99','2.00');$unpriced=fixture_bulk('QA-BULK-NONE','','');
check_bulk('REST permission: anonymous denied on all five routes',function(){wp_set_current_user(0);try{foreach(['catalog','preview','apply','history','undo'] as $route)bad_bulk($route,[]);}finally{wp_set_current_user(1);}});
check_bulk('catalog includes independent USD and GBP values',function()use($a){$r=good_bulk('catalog');$rows=array_values(array_filter($r['rows'],fn($x)=>$x['id']===$a));demand($rows[0]['usd']['regular']==='19.99'&&$rows[0]['gbp']['regular']==='22.00');});
check_bulk('USD preview is read-only and Apply persists only USD',function()use($a){$before=price_bulk($a);$op=selected_bulk($a);demand(price_bulk($a)===$before,'Preview mutated product');demand($op['changes'][0]['after']['sale']==='14.99','Exact USD calculation wrong');$r=apply_bulk($op);demand($r['state']==='applied'&&$r['saved']===1);demand(price_bulk($a)===['19.99','14.99']);demand(price_bulk($a,'GBP')===['22.00',''],'GBP changed with USD');undo_bulk($op);demand(price_bulk($a)===$before,'Undo did not restore USD');});
check_bulk('GBP exact discount Apply and guarded Undo',function()use($a){$op=selected_bulk($a,'GBP');demand($op['changes'][0]['after']['sale']==='16.50');apply_bulk($op);demand(price_bulk($a,'GBP')===['22.00','16.50']);demand(price_bulk($a)===['19.99','']);undo_bulk($op);demand(price_bulk($a,'GBP')===['22.00','']);});
check_bulk('same SKU USD+GBP import saves two independent rows',function()use($a){$op=good_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'QA-BULK-A','currency'=>'USD','regular'=>'29.99','sale'=>'19.99'],['sku'=>'QA-BULK-A','currency'=>'GBP','regular'=>'26.00','discount'=>'25']]]);demand(count($op['changes'])===2);$r=apply_bulk($op);demand($r['saved']===2);demand(price_bulk($a)===['29.99','19.99']);demand(price_bulk($a,'GBP')===['26.00','19.50']);$r=undo_bulk($op);demand($r['restored']===2);demand(price_bulk($a)===['19.99','']&&price_bulk($a,'GBP')===['22.00','']);});
check_bulk('duplicate SKU/currency rejected',function(){bad_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'QA-BULK-A','currency'=>'USD','discount'=>'25'],['sku'=>'qa-bulk-a','currency'=>'USD','discount'=>'30']]]);});
check_bulk('unknown SKU and unsupported currency rejected',function(){bad_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'unknown-qa','currency'=>'USD','discount'=>'25']]]);bad_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'QA-BULK-A','currency'=>'EUR','regular'=>'5600']]]);});
check_bulk('conflicting discount and sale rejected by server',function(){bad_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'QA-BULK-A','currency'=>'GBP','discount'=>'25','sale'=>'10.00']]]);});
check_bulk('USD accepts exact regular and sale prices without listing exemptions',function()use($a){$op=good_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'QA-BULK-A','currency'=>'USD','regular'=>'23.70','sale'=>'17.25']]]);apply_bulk($op);demand(price_bulk($a)===['23.70','17.25']);undo_bulk($op);});
check_bulk('malformed amounts and free/equal sales rejected',function(){foreach(['-1','1e2','0','20.001','NaN','£20','1000000',[]] as $v)bad_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'QA-BULK-A','currency'=>'GBP','regular'=>$v]]]);foreach(['0','22.00','25.00'] as $v)bad_bulk('preview',['mode'=>'import','rows'=>[['sku'=>'QA-BULK-A','currency'=>'GBP','sale'=>$v]]]);});
check_bulk('empty selection, unknown selected product, empty import, >500 rows rejected',function(){bad_bulk('preview',['mode'=>'selected','ids'=>[],'discount'=>'25']);bad_bulk('preview',['mode'=>'selected','ids'=>[999999999],'discount'=>'25']);bad_bulk('preview',['mode'=>'import','rows'=>[]]);bad_bulk('preview',['mode'=>'import','rows'=>array_fill(0,501,['sku'=>'QA-BULK-A','currency'=>'GBP','discount'=>'25'])]);});
check_bulk('global fixed previews skip unpriced products and do not write',function()use($a,$unpriced){foreach(['USD','PKR','GBP'] as $cur){$before=price_bulk($a,$cur);$op=good_bulk('preview',['mode'=>'global','currency'=>$cur,'discount'=>'25']);demand(count($op['changes'])>0);demand(!in_array($unpriced,array_column($op['changes'],'id'),true));demand(count($op['skipped'])>0);demand(price_bulk($a,$cur)===$before);}});
check_bulk('random all/selected discounts stay within actual 25–30%',function()use($a,$b){foreach(['USD','GBP'] as $cur)foreach(['random_selected','random_global'] as $mode)for($i=0;$i<12;$i++){$op=good_bulk('preview',['mode'=>$mode,'currency'=>$cur,'ids'=>[$a,$b]]);foreach($op['changes'] as $c){$d=100*(1-(float)$c['after']['sale']/(float)$c['after']['regular']);demand($d>=25-1e-7&&$d<=30+1e-7,'Out-of-range discount '.$d);}}});
check_bulk('stale preview refuses entire batch without partial writes',function()use($a,$b){$op=good_bulk('preview',['mode'=>'selected','currency'=>'GBP','discount'=>'25','ids'=>[$a,$b]]);$p=wc_get_product($b);$p->update_meta_data('_instapass_gbp_regular_price','3.00');$p->save();try{bad_bulk('apply',['token'=>$op['token']]);demand(price_bulk($a,'GBP')===['22.00','']);}finally{$p=wc_get_product($b);$p->update_meta_data('_instapass_gbp_regular_price','2.00');$p->save();}});
check_bulk('used preview cannot replay',function()use($a){$op=selected_bulk($a,'GBP');apply_bulk($op);bad_bulk('apply',['token'=>$op['token']]);undo_bulk($op);});
check_bulk('expired and other-user previews refused',function()use($a){$op=selected_bulk($a,'GBP');$v=get_transient('ipcb_preview_'.$op['token']);$v['created']=time()-1000;set_transient('ipcb_preview_'.$op['token'],$v,900);bad_bulk('apply',['token'=>$op['token']]);$op=selected_bulk($a,'GBP');$v=get_transient('ipcb_preview_'.$op['token']);$v['user']=999;set_transient('ipcb_preview_'.$op['token'],$v,900);bad_bulk('apply',['token'=>$op['token']]);});
check_bulk('newer edit blocks Undo without overwriting owner change',function()use($a){$op=selected_bulk($a,'GBP');apply_bulk($op);$p=wc_get_product($a);$p->update_meta_data('_instapass_gbp_sale_price','12.00');$p->save();bad_bulk('undo',['token'=>$op['token']]);demand(price_bulk($a,'GBP')===['22.00','12.00']);$p=wc_get_product($a);$p->delete_meta_data('_instapass_gbp_sale_price');$p->save();});
check_bulk('lock refuses concurrent Apply and is not stolen',function()use($a){$op=selected_bulk($a,'GBP');add_option(Instapass_Control_Bulk::LOCK,['token'=>'held-by-other','time'=>time()]);try{bad_bulk('apply',['token'=>$op['token']]);demand(get_option(Instapass_Control_Bulk::LOCK)['token']==='held-by-other');}finally{delete_option(Instapass_Control_Bulk::LOCK);}});
check_bulk('post-save audit failure records each changed product exactly once and permits safe Undo',function()use($a){$op=selected_bulk($a,'GBP');$opt='ipcb_audit_'.$op['token'];$blocked=false;$filter=function($v,$old)use(&$blocked){if(!$blocked&&count($v['saved']??[])===1&&empty($v['inflight'])){$blocked=true;return $old;}return $v;};add_filter('pre_update_option_'.$opt,$filter,10,2);try{$r=apply_bulk($op);}finally{remove_filter('pre_update_option_'.$opt,$filter,10);}demand($blocked,'Failure injection did not run');$audit=get_option($opt);demand(count($audit['saved'])===1,'Audit duplicated saved product');undo_bulk($op);demand(price_bulk($a,'GBP')===['22.00','']);});
check_bulk('0 discount removes a non-.99 generated USD sale',function()use($b){$p=wc_get_product($b);$p->set_sale_price('1.45');$p->set_price('1.45');$p->save();try{$op=selected_bulk($b,'USD','0');apply_bulk($op);demand(price_bulk($b)===['1.99','']);}finally{$p=wc_get_product($b);$p->set_sale_price('');$p->set_price('1.99');$p->save();}});
check_bulk('sale schedules and stock/status remain untouched',function()use($a){$p=wc_get_product($a);$p->set_date_on_sale_from(time()+86400);$p->set_date_on_sale_to(time()+172800);$p->save();$p=wc_get_product($a);$before=[$p->get_date_on_sale_from()->getTimestamp(),$p->get_date_on_sale_to()->getTimestamp(),$p->get_status(),$p->get_stock_status()];$op=selected_bulk($a);apply_bulk($op);$p=wc_get_product($a);demand([$p->get_date_on_sale_from()->getTimestamp(),$p->get_date_on_sale_to()->getTimestamp(),$p->get_status(),$p->get_stock_status()]===$before);demand($p->get_price('edit')==='19.99','Future sale became active early');undo_bulk($op);});
check_bulk('existing catalog and orders preserved',function()use($originals,$products_before){foreach($originals as $id=>$v){$o=wc_get_order($id);demand([$o->get_currency(),$o->get_total(),$o->get_status()]===$v,'Existing order changed');}foreach($products_before as $id=>$v){$p=wc_get_product($id);demand([$p->get_regular_price('edit'),$p->get_sale_price('edit'),$p->get_meta('_instapass_gbp_regular_price',true,'edit'),$p->get_meta('_instapass_gbp_sale_price',true,'edit'),$p->get_status(),$p->get_stock_status()]===$v,'Existing catalog product changed');}});
check_bulk('malformed request types and unsupported import fields rejected',function()use($a){foreach([['mode'=>[]],['mode'=>'selected','currency'=>[],'ids'=>[$a]],['mode'=>'selected','discount'=>[],'ids'=>[$a]],['mode'=>'selected','discount'=>'25','ids'=>[[]]]] as $body)bad_bulk('preview',$body);foreach([['regular'=>null],['currency'=>[]],['random'=>true,'regular'=>'19.50']] as $v)bad_bulk('preview',['mode'=>'import','rows'=>[array_merge(['sku'=>'QA-BULK-A','currency'=>'USD'],$v)]]);bad_bulk('apply',['token'=>[]]);bad_bulk('undo',['token'=>[]]);});
check_bulk('second product save failure leaves an accurate partial batch and safe Undo',function()use($a,$b){$op=good_bulk('preview',['mode'=>'selected','currency'=>'GBP','discount'=>'25','ids'=>[$a,$b]]);$hook=function($p)use($b){if($p->get_id()===$b)throw new RuntimeException('Injected second-product save failure');};add_action('woocommerce_before_product_object_save',$hook,10,1);try{$r=apply_bulk($op);}finally{remove_action('woocommerce_before_product_object_save',$hook,10);}demand($r['state']==='partial'&&$r['saved']===1&&count($r['errors'])===1);demand(price_bulk($a,'GBP')===['22.00','16.50']&&price_bulk($b,'GBP')===['2.00','']);undo_bulk($op);demand(price_bulk($a,'GBP')===['22.00','']);});
check_bulk('history-write failure stops before any product save',function()use($a){$op=selected_bulk($a,'GBP');$hook=fn($v,$old)=>$old;add_filter('pre_update_option_ipcb_history',$hook,10,2);try{bad_bulk('apply',['token'=>$op['token']]);}finally{remove_filter('pre_update_option_ipcb_history',$hook,10);}demand(price_bulk($a,'GBP')===['22.00','']);demand(!get_option('ipcb_audit_'.$op['token']));});

function raw_pkr($id){$p=wc_get_product($id);return [(string)$p->get_meta('_instapass_pkr_regular_price'),(string)$p->get_meta('_instapass_pkr_sale_price')];}
function catalog_row($id){foreach(good_bulk('catalog')['rows'] as $row)if($row['id']===$id)return $row;throw new RuntimeException('Missing catalog row');}
function imported($rows){return good_bulk('preview',['mode'=>'import','rows'=>$rows]);}
